.interactive-item-container .chat-request-timing {
	display: inline-grid;
	overflow: hidden;
}

.interactive-item-container .chat-request-timestamp:focus-visible {
	outline: var(--vscode-strokeThickness) solid var(--vscode-focusBorder);
	outline-offset: var(--vscode-spacing-size20);
}

.interactive-item-container .chat-request-timing > * {
	grid-area: 1 / 1;
	justify-self: end;
	text-align: right;
	transition: opacity 160ms ease, transform 160ms ease;
}

.interactive-item-container .chat-request-flip-reset .chat-request-timing > * {
	transition: none;
}

.interactive-item-container .chat-request-timing .chat-request-full-date {
	opacity: 0;
	transform: translateY(100%);
}

.interactive-item-container .chat-request-timestamp.chat-request-flip-down .chat-request-timing .chat-request-full-date {
	transform: translateY(-100%);
}

.interactive-item-container .chat-request-timestamp.chat-request-flip-active .chat-request-timing.has-alternate .chat-request-relative,
.interactive-item-container .chat-request-timestamp:focus-visible .chat-request-timing.has-alternate .chat-request-relative {
	opacity: 0;
	transform: translateY(-100%);
}

.interactive-item-container .chat-request-timestamp.chat-request-flip-down.chat-request-flip-active .chat-request-timing.has-alternate .chat-request-relative {
	transform: translateY(100%);
}

.interactive-item-container .chat-request-timestamp.chat-request-flip-active .chat-request-timing.has-alternate .chat-request-full-date,
.interactive-item-container .chat-request-timestamp:focus-visible .chat-request-timing.has-alternate .chat-request-full-date {
	opacity: 1;
	transform: translateY(0);
}

.interactive-item-container .chat-response-model-details {
	min-width: 0;
	overflow: hidden;
	text-overflow: ellipsis;
}

.interactive-item-container.interactive-response .chat-footer-toolbar .chat-footer-details.hidden {
	display: none;
}

@media (prefers-reduced-motion: reduce) {
	.interactive-item-container .chat-response-timing > *,
	.interactive-item-container .chat-request-timing > * {
		transition: none;
	}
}

.interactive-item-container.interactive-request:not(.show-verbose-details):not(.editing):not(.editing-input) .chat-request-timestamp-container {
	display: none;
}

.interactive-item-container .value {
	width: 100%;
}

.interactive-item-container .chat-request-timestamp-container {
	width: 100%;
}

.interactive-item-container.interactive-request.editing .chat-request-timestamp-container {
	align-items: center;
	height: 22px;
	margin-top: -22px;
	pointer-events: none;
}

.interactive-item-container.interactive-request.editing .chat-request-timestamp {
	pointer-events: auto;
}

.monaco-workbench:not(.agent-sessions-workbench) .interactive-item-container.interactive-request.editing .chat-request-timestamp-container {
	box-sizing: border-box;
	padding-inline-end: var(--vscode-spacing-size160);
}

.interactive-item-container .completed-response-disclosure {
	width: 100%;
	margin-bottom: var(--vscode-spacing-size80);
	interpolate-size: allow-keywords;

	&::details-content {
		block-size: 0;
		box-sizing: border-box;
		overflow: hidden;
		opacity: 0;
		margin-inline-start: var(--vscode-spacing-size60);
		padding-inline-start: var(--vscode-spacing-size120);
		border-inline-start: var(--vscode-strokeThickness) solid var(--vscode-chat-requestBorder);
		border-image: linear-gradient(to bottom, var(--vscode-chat-requestBorder) 0 calc(100% - var(--vscode-spacing-size80)), transparent calc(100% - var(--vscode-spacing-size80))) 1;
		transition:
			block-size 180ms cubic-bezier(0.2, 0, 0, 1),
			opacity 140ms cubic-bezier(0.2, 0, 0, 1),
			content-visibility 180ms allow-discrete;
	}

	&[open]::details-content {
		block-size: auto;
		opacity: 1;
	}
}

.interactive-item-container .completed-response-disclosure:not([open]) {
	margin-bottom: var(--vscode-spacing-size160);
}

.interactive-item-container .completed-response-summary {
	width: fit-content;
	max-width: 100%;
	padding: 0;
	border-radius: var(--vscode-cornerRadius-small);
