	.interactive-list > .monaco-list:focus > .monaco-scrollable-element > .monaco-list-rows > .monaco-list-row.focused.request {
		outline: none !important;

		.interactive-item-container .value .rendered-markdown {
			outline: 1px solid var(--vscode-focusBorder);
		}
	}

	.interactive-request.editing .rendered-markdown,
	.interactive-request.editing .value {
		display: none;
	}

	.interactive-request.editing-input .rendered-markdown {
		outline: 1px solid var(--vscode-focusBorder);
	}

	.interactive-request.editing {
		padding: 0px;

		.interactive-input-part .chat-input-container .interactive-input-editor .monaco-editor .native-edit-context {
			opacity: 0;
		}
	}
}

.editor-instance .interactive-session .interactive-item-container.interactive-response .checkpoint-restore-container {

	.checkpoint-label-text,
	.monaco-toolbar {
		background-color: var(--vscode-editor-background);
	}
}

.chat-buttons-container {
	display: flex;
	gap: 8px;
	margin-top: 0px;
	flex-wrap: wrap;
	flex-basis: 100%;
	padding: 0 8px;
	margin: 8px 0;

	& .monaco-button.monaco-dropdown-button {
		padding: 0 3px;
	}
}

.interactive-item-container .chat-command-button .monaco-button,
.chat-buttons-container .monaco-button:not(.monaco-dropdown-button) {
	text-align: left;
	width: initial;
}

.interactive-item-container .chat-edit-input-container {
	width: 100%;
}

.interactive-session .interactive-item-container.interactive-request.editing > .value > .chat-attached-context {
	padding: 0px 16px;
}

.chat-row-disabled-overlay,
.interactive-item-container .chat-edit-input-container .chat-editing-session,
.chat-input-overlay {
	display: none;
}

.chat-row-disabled-overlay.disabled,
.chat-input-overlay.disabled {
	position: absolute;
	inset: 0;
	background-color: var(--vscode-sideBar-background);
	opacity: 0.6;
	display: flex;
	z-index: 101;
	user-select: none;
	cursor: default;
}

.interactive-session .focused-input-dom {
	position: absolute;
	top: -50000px;
	width: 1px;
	height: 1px;
}


.interactive-session .chat-attached-context .chat-attached-context-attachment.implicit.disabled:hover {
	cursor: pointer;
	border-style: solid;
	background-color: var(--vscode-toolbar-hoverBackground);
}

/* Chat Suggest Next Widget */
/* Suggested Actions widget - reuses chat-welcome-view-suggested-prompts styling */

.interactive-session > .chat-suggest-next-widget {
	/* Override positioning from welcome view styles (relative instead of absolute) */
	position: relative;
	bottom: auto;
	left: auto;
	right: auto;
	margin: 0 0 0 0;
	/* Keep standard padding with space for title */
	padding: 32px 16px 8px 16px;
	/* Left align buttons to match standard welcome view */
	justify-content: flex-start;
	/* Ensure flex layout is properly applied */
	display: flex;
	flex-wrap: wrap;
	gap: 8px;
}

.chat-welcome-view-suggested-prompt.chat-suggest-next-has-dropdown {
	padding-right: 12px;
}

/* Dropdown container for chevron in suggested prompt buttons - provides larger hit area */
.chat-welcome-view-suggested-prompt > .chat-suggest-next-dropdown {
	display: flex;
	align-items: center;
	justify-content: center;
	height: 100%;
	margin: -1px -8px -1px 0;
	/* Extend to button edge, accounting for button padding */
	padding: 0 4px 0 2px;
	gap: 4px;
	cursor: pointer;
	border-top-right-radius: 4px;
	border-bottom-right-radius: 4px;
	box-sizing: border-box;
}

.chat-welcome-view-suggested-prompt > .chat-suggest-next-dropdown:hover {
	background-color: var(--vscode-toolbar-hoverBackground);
}

.chat-welcome-view-suggested-prompt > .chat-suggest-next-dropdown:focus {
	outline: 1px solid var(--vscode-focusBorder);
	outline-offset: -1px;
}

/* Chevron icon in dropdown container */
.chat-welcome-view-suggested-prompt .codicon-chevron-down.dropdown-chevron {
	font-size: 12px;
	opacity: 0.7;
	flex-shrink: 0;
}

.chat-welcome-view-suggested-prompt > .chat-suggest-next-dropdown:hover .dropdown-chevron,
.chat-welcome-view-suggested-prompt > .chat-suggest-next-dropdown:focus .dropdown-chevron {
	opacity: 1;
}

/* Vertical separator between label and chevron in suggested next actions */
.chat-suggest-next-dropdown > .chat-suggest-next-separator {
	width: 1px;
	height: 16px;
	background-color: currentColor;
	opacity: 0.5;
	border-radius: 1px;
	align-self: center;
	flex-shrink: 0;
}

/* Show more attachments button styling */
.chat-attachments-show-more-button {
	opacity: 0.8;
	transition: opacity 0.2s ease;
}

.chat-attachments-show-more-button:hover {
	opacity: 1;
	background-color: var(--vscode-list-hoverBackground) !important;
}

.chat-attachments-show-more-button:focus {
	outline: 1px solid var(--vscode-focusBorder);
	outline-offset: -1px;
}

.chat-attachments-show-more-button .chat-attached-context-custom-text {
	font-style: italic;
	color: var(--vscode-descriptionForeground);
}

/* Pending request styles */
.interactive-item-container.pending-request {
	opacity: 0.7;

	.request-hover {
		top: -17px !important;
	}
}

/* Drag handle for reordering pending messages */
.interactive-item-container .chat-pending-drag-handle {
	position: absolute;
	left: 0;
	top: 50%;
	transform: translateY(-50%);
	width: 16px;
	display: flex;
	align-items: center;
	justify-content: center;
	cursor: grab;
	opacity: 0;
	transition: opacity 0.15s;
	color: var(--vscode-descriptionForeground);
	margin-top: -4px;
	/* visually center with overlaid top controls */
}

.interactive-item-container.pending-request:hover .chat-pending-drag-handle {
	opacity: 1;
}

/* Dragging state */
.interactive-item-container.chat-pending-dragging {
	opacity: 0.4;
}

/* Insertion indicator */
.chat-pending-insert-indicator {
	position: absolute;
	height: 2px;
	background: var(--vscode-focusBorder);
	pointer-events: none;
	z-index: 100;
	display: none;
}

.interactive-item-container .chat-request-status {
	color: var(--vscode-descriptionForeground);
	font-size: var(--vscode-chat-font-size-body-xs);
	margin-top: 2px;
	text-align: right;
}

/* Pending divider styles */
.interactive-item-container.pending-divider {
	padding: 8px 16px;
}

.interactive-item-container.pending-divider .pending-divider-content {
	display: flex;
	align-items: center;
	gap: 8px;
}

.interactive-item-container.pending-divider .pending-divider-label {
	font-size: var(--vscode-chat-font-size-body-xs);
	font-weight: 500;
	text-transform: uppercase;
	letter-spacing: 0.5px;
	color: var(--vscode-descriptionForeground);
}

/* Outline removal except for HC themes */
.monaco-workbench:not(.hc-black):not(.hc-light) .interactive-list > .monaco-list > .monaco-scrollable-element > .monaco-list-rows > .monaco-list-row.focused.response {
	outline: none !important;
}

/* Standalone dictation / Voice Mode buttons (shown when the segmented voice pill
	isn't active). Give them the same control tier as the send button they sit
	beside — a 22×22 surface with the compact 12px glyph used by the agent /
	model pickers — so the mic group reads as one consistent row in every state:
	dictation idle / recording / preparing / connecting, and Voice Mode idle /
	connecting / listening / speaking / disconnect.

	On their own they lose the segmented pill's enclosure, so each one carries a
	circular outline of its own and reads as a single-cell version of it rather
	than a bare glyph. The ring uses the pill's exact border declaration so the
	two enclosures are indistinguishable when the UI swaps between them —
	`input.border` is `null` outside high contrast and resolves to a soft
	20%-alpha `editorWidget.border`, and in high contrast it resolves to
	`contrastBorder` so the ring stays fully opaque there. */
.interactive-session .chat-input-toolbars > .chat-execute-toolbar .monaco-action-bar .action-item > .action-label.codicon-mic,
.interactive-session .chat-input-toolbars > .chat-execute-toolbar .monaco-action-bar .action-item > .action-label.codicon-mic-filled,
.interactive-session .chat-input-toolbars > .chat-execute-toolbar .monaco-action-bar .action-item > .action-label.codicon-mic-download-compact,
.interactive-session .chat-input-toolbars > .chat-execute-toolbar .monaco-action-bar .action-item > .action-label.codicon-voice-mode-compact,
.interactive-session .chat-input-toolbars > .chat-execute-toolbar .monaco-action-bar .action-item > .action-label.codicon-loading-compact,
.interactive-session .chat-input-toolbars > .chat-execute-toolbar .monaco-action-bar .action-item > .action-label.codicon-debug-disconnect-compact {
	box-sizing: border-box;
	width: 22px;
	height: 22px;
	justify-content: center;
	border: var(--vscode-strokeThickness) solid var(--vscode-input-border, var(--vscode-editorWidget-border));
	border-radius: var(--vscode-cornerRadius-circle);
	font-size: var(--vscode-codiconFontSize-compact);
}

@keyframes chat-voice-icon-glow {
	0%,
	100% {
		box-shadow: 0 0 2px var(--chat-voice-icon-glow-color);
	}

	50% {
		box-shadow: 0 0 5px var(--chat-voice-icon-glow-color);
	}
}

/* Voice mode mic glyph: tinted with the same theme-derived accent as the ambient
	glow (published as `--voice-accent` by the glow controller). The glow keeps the
	button's resting shape — only its color and the pulse change between states, so
	the control never morphs from a circle into a rounded square mid-session. */
.chat-input-container.voice-active .chat-input-toolbars .action-label.codicon-voice-mode-compact {
	--chat-voice-icon-glow-color: color-mix(in srgb, var(--voice-accent, var(--vscode-charts-blue, #58a6ff)) 40%, transparent);
	color: var(--voice-accent, var(--vscode-charts-blue, #58a6ff)) !important;
	border-radius: var(--vscode-cornerRadius-circle);
}

.monaco-workbench.monaco-enable-motion .chat-input-container.voice-active.voice-listening .chat-input-toolbars .action-label.codicon-voice-mode-compact,
.monaco-workbench.monaco-enable-motion .chat-input-container.voice-active.voice-speaking .chat-input-toolbars .action-label.codicon-voice-mode-compact {
	animation: chat-voice-icon-glow 1.4s ease-in-out infinite;
}

/* Voice mode: green disconnect button. This has to out-specify the blanket
	`icon-foreground !important` rule that colors every toolbar codicon, so it
	carries the full toolbar path rather than a short `.chat-input-container`
	prefix — with equal `!important` the higher specificity wins, and the short
	form silently lost the cascade and rendered grey. */
.interactive-session .chat-input-toolbars > .chat-execute-toolbar .monaco-action-bar .action-item > .action-label.codicon-debug-disconnect-compact {
	color: var(--vscode-charts-green, #3fb950) !important;
}

/*
 * Voice mode connecting indicator: only spin the spinner glyph, not the whole
 * button. Otherwise the action-label (including its hover background) rotates
 * along with the icon.
 */
.chat-input-container .chat-input-toolbars .action-label.codicon-loading,
.chat-input-container .chat-input-toolbars .action-label.codicon-loading-compact {
	animation: none;
}

.chat-input-container .chat-input-toolbars .action-label.codicon-loading::before,
.chat-input-container .chat-input-toolbars .action-label.codicon-loading-compact::before {
	display: inline-block;
	transform-origin: center center;
	animation: codicon-spin 1.5s steps(30) infinite;
}

.monaco-reduce-motion .chat-input-container .chat-input-toolbars .action-label.codicon-loading::before,
.monaco-reduce-motion .chat-input-container .chat-input-toolbars .action-label.codicon-loading-compact::before {
	animation: none;
}

.monaco-reduce-motion .action-item.chat-restore-checkpoint-item.confirming .action-label:first-child {
	animation: none;
	background: none;
	-webkit-text-fill-color: currentColor;
	color: var(--vscode-foreground);
}

/* Dictation model download: while the on-device speech-to-text model downloads
	on first use, the toolbar shows a download icon wrapped by a circular
	progress ring (see DictationDownloadActionViewItem) instead of a spinning
	mic, so the wait reads as a determinate download rather than a hang. */
.monaco-action-bar .action-item.dictation-download-item {
	position: relative;
}

.monaco-action-bar .action-item.dictation-download-item > .dictation-download-ring {
	position: absolute;
	top: 50%;
	left: 50%;
	/* Sized to hug the compact 12px download glyph rather than the full button. */
	width: 16px;
	height: 16px;
	transform: translate(-50%, -50%) rotate(-90deg);
	pointer-events: none;
}

.monaco-action-bar .action-item.dictation-download-item > .dictation-download-ring .dictation-download-ring-track {
	fill: none;
	stroke: var(--vscode-progressBar-background);
	stroke-width: 1.5;
	opacity: 0.25;
}

/* In high-contrast themes progressBar.background is the solid contrastBorder;
	keep the track fully opaque so it stays visible against the arc. */
.hc-black .action-item.dictation-download-item > .dictation-download-ring .dictation-download-ring-track,
.hc-light .action-item.dictation-download-item > .dictation-download-ring .dictation-download-ring-track {
	opacity: 1;
}

.monaco-action-bar .action-item.dictation-download-item > .dictation-download-ring .dictation-download-ring-progress {
	fill: none;
	stroke: var(--vscode-progressBar-background);
	stroke-width: 1.5;
	stroke-linecap: round;
}

.monaco-workbench.monaco-enable-motion .action-item.dictation-download-item > .dictation-download-ring .dictation-download-ring-progress {
	transition: stroke-dashoffset 120ms ease;
}

/* Keep the progress arc moving while the model downloads or loads so the
	affordance reads as active even between percentage updates. Gated on
	enable-motion to respect reduced motion. */
.monaco-workbench.monaco-enable-motion .dictation-download-ring {
	animation: dictation-download-ring-spin 1.2s linear infinite;
}

.monaco-workbench.monaco-enable-motion .action-item.dictation-download-item > .dictation-download-ring.indeterminate .dictation-download-ring-progress {
	transition: none;
}

@keyframes dictation-download-ring-spin {
	from {
		transform: translate(-50%, -50%) rotate(-90deg);
	}
	to {
		transform: translate(-50%, -50%) rotate(270deg);
	}
}
